const items = $input.all();
if (items.length === 0) return [];
const emails = [];
for (const item of items) {
  const e = item.json;
  const subject = (e.Subject || e.subject || '(件名なし)').substring(0, 200);
  const from = e.From || e.from || '不明';
  const snippet = (e.snippet || '').substring(0, 300);
  const messageId = e.id;
  let dateISO;
  try {
    const ts = e.internalDate ? Number(e.internalDate) : null;
    dateISO = ts ? new Date(ts).toISOString() : (e.date ? new Date(e.date).toISOString() : new Date().toISOString());
  } catch(_) { dateISO = new Date().toISOString(); }
  emails.push({ subject, from, snippet, messageId, dateISO });
}
const emailList = emails.map((e, i) => `${i + 1}. 件名: ${e.subject}, 差出人: ${e.from}, スニペット: ${e.snippet}`).join('\n');
const prompt = `以下のメール一覧を「重要」「不要」「確認」に分類してください。\n\n分類基準:\n- 重要: 銀行・金融通知、インフラ関連（Oracle Cloud, AWS等）、セキュリティ関連、個人宛の重要連絡\n- 不要: 広告・宣伝メール、自動通知（GitHub等）、飲食店プロモーション、ポイント付与通知\n- 確認: 上記のどちらにも明確に該当しないもの\n\nメール一覧:\n${emailList}\n\nJSON配列で返答してください（他のテキストは不要）:\n[{"index": 1, "importance": "重要"}, {"index": 2, "importance": "不要"}, ...]`;
const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json', temperature: 0.1, maxOutputTokens: 1000 }
});
return [{ json: { geminiBody, emails } }];

const geminiResponse = $input.first().json;
const emailData = $('PrepareClassify').first().json.emails;
let classifications = [];
try {
  const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    classifications = JSON.parse(jsonMatch[0]);
  }
} catch (e) { throw new Error('BuildNotionBody: Gemini分類結果のパースに失敗: ' + e.message); }
const classMap = {};
for (const c of classifications) {
  classMap[c.index] = c.importance || '確認';
}
return emailData.map((email, i) => {
  const importance = classMap[i + 1] || '確認';
  const body = {
    parent: { database_id: '2ff2570f-e49f-8119-aaaf-f688605e5aa3' },
    properties: {
      '件名': { title: [{ text: { content: email.subject } }] },
      '差出人': { rich_text: [{ text: { content: email.from.substring(0, 2000) } }] },
      '日時': { date: { start: email.dateISO } },
      '重要度': { select: { name: importance } },
      'スニペット': { rich_text: [{ text: { content: email.snippet } }] },
      'ステータス': { select: { name: '未読' } }
    }
  };
  return { json: { requestBody: JSON.stringify(body), messageId: email.messageId } };
});

const prepItems = $('BuildNotionBody').all();
return prepItems.map(item => ({
  json: { messageId: item.json.messageId }
}));
